contract=dict(phase=a.phase,route_selection="canonical downstream0 for each approach; avoid tripling identical upstream prefixes" if a.phase==0 else "all routes",evaluation=str(a.evaluation),additional_evaluations=[str(x) for x in a.additional_evaluations],nominal=str(a.output/'nominal_same_data.npz'),entries=entries,updates_each=a.updates,total_updates=a.updates*6,checkpoints_every=25,batch=64,optimizer='Adam3e-4,gradientclip1',horizons=[5,15,50,150],initialization='Three independent initializations per learned model; paired seeds/data/batches/architecture',role='Declared source-group TRAIN/DEV pilot, not independent TEST or completedP3',M0='Ridge1 linear ARX fit to the same rough TRAIN declared ground-phase transitions; this empirical baseline is distinct from the prior flat-only nominal model',M1='Same-data M0 plus terrain/history correction',M2='Same input/GRU/head/integration, predicts full dynamic increment without ARX contribution',training_counts=counts,terrain='15local yaw-aligned samples with height/slopes/variation/support; fixedmap raster queried at predicted future states, no future physical history',policy='RB225/H75/physics unchanged; supervised predictor identification only, not controller PPO or domain-randomized policy training',selection='Mean max1sXY on fixed DEV windows; report all saved checkpoints and tails, not convergence from loss plateau',expected_wallclock_s=[400,1200],hard_limit_s=1500,stop='One six-run queue, first error or25min; no automatic continuation or threshold changes',acceptance='No long-horizon adoption until full relevant horizon/geometry errors fit task clearance; compare all seeds and retain failures',source_revision=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip())
